import type { ComponentProps } from "@types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { VerticalTabBarClasses } from "../vertical-tab-bar.styles";

export const VerticalTabBarTitle = forwardRef<HTMLDivElement, ComponentProps>(
  ({ className, children, ...props }, ref) => {
    const classes = clsx(VerticalTabBarClasses.title, className);

    return (
      <div ref={ref} className={classes} {...props}>
        {children}
      </div>
    );
  },
);

VerticalTabBarTitle.displayName = "VerticalTabBar.Title";
